import math, random
from math import comb

def binom_cdf(k, n, p):
    return sum(comb(n, i) * p**i * (1-p)**(n-i) for i in range(0, k+1))

print("== P(all k runs pass) ==")
for k in (1,2,3,5,8,10,14,20,59):
    print(k, round(0.8**k,3), round(0.95**k,3))

print("== Wilson 95% interval ==")
def wilson(s, n, z=1.96):
    p = s/n
    d = 1 + z*z/n
    c = (p + z*z/(2*n))/d
    h = z*math.sqrt(p*(1-p)/n + z*z/(4*n*n))/d
    return round(c-h,3), round(c+h,3)
for s,n in ((3,7),(5,5),(10,10),(9,10),(8,10),(19,20),(16,20),(29,30)):
    print(s,n,wilson(s,n))

print("== one-sample exact test: H0 p<=0.80 vs H1 p=0.95, alpha=.05 ==")
for n in range(5,80):
    # smallest c such that P(X>=c | p=.8) <= .05
    c = next(c for c in range(0,n+2) if 1-binom_cdf(c-1,n,0.8) <= 0.05)
    power = 1-binom_cdf(c-1,n,0.95) if c<=n else 0
    if n in (10,15,20,25,30,35,40,50,60) :
        print(n, "need >=",c,"passes; power", round(power,3))
first = None
for n in range(5,200):
    c = next(c for c in range(0,n+2) if 1-binom_cdf(c-1,n,0.8) <= 0.05)
    power = 1-binom_cdf(c-1,n,0.95) if c<=n else 0
    if power>=0.8:
        print("smallest n with power>=0.8:", n, c, round(power,3)); break

print("== two-arm compare (A=0.80 vs B=0.95), normal approx per-arm n ==")
for za,lab in ((1.645,"one-sided .05"),(1.96,"two-sided .05")):
    zb=0.8416
    n=(za+zb)**2*(0.8*0.2+0.95*0.05)/(0.15**2)
    print(lab, round(n,1))

print("== per-stage proxy: detect stage success 0.95 vs 0.99 with N page-level trials ==")
for n in (50,100,200,300):
    print(n, "se at .95:", round(math.sqrt(.95*.05/n),4))

print("== lognormal fit p50=3, p95=9 ==")
mu=math.log(3); sigma=math.log(3)/1.6449
def q(z): return math.exp(mu+sigma*z)
for lab,z in (("p75",0.6745),("p90",1.2816),("p95",1.6449),("p99",2.3263),("p99.9",3.0902)):
    print(lab, round(q(z),1))
def sf(t):
    z=(math.log(t)-mu)/sigma
    return 0.5*math.erfc(z/math.sqrt(2))
for t in (5,6,7,8,9,10,12,15,20,25,30):
    print("P(lat>%ds)=%.4f"%(t,sf(t)))

random.seed(7)
def lat(h):
    if random.random()<h: return float('inf')
    return math.exp(random.gauss(mu,sigma))

def call_plain(h, timeout, max_attempts=4):
    t=0; n=0
    for a in range(max_attempts):
        n+=1
        l=lat(h)
        if l<=timeout: return t+l, n
        t+=timeout
    return t, n   # gave up

def call_hedged(h, hedge, timeout, max_rounds=2):
    # primary; if no answer by `hedge`, launch a second; first to finish wins; whole round bounded by `timeout`
    t=0; n=0
    for r in range(max_rounds):
        n+=1
        a=lat(h)
        if a<=hedge: return t+a, n
        n+=1
        b=hedge+lat(h)
        m=min(a,b)
        if m<=timeout: return t+m, n
        t+=timeout
    return t, n

def loop(policy, h, ncalls=65, trials=4000):
    tot=[]; calls=[]
    for _ in range(trials):
        T=0; N=0
        for _ in range(ncalls):
            t,n=policy(h); T+=t; N+=n
        tot.append(T); calls.append(N)
    tot.sort()
    return (round(tot[len(tot)//2]), round(tot[int(.95*len(tot))]), round(tot[int(.99*len(tot))]), round(sum(calls)/len(calls)/ncalls,3))

print("== one agent loop of 65 sequential calls: total LLM wait seconds p50/p95/p99, calls-per-logical-call ==")
for h in (0.0,0.01,0.03,0.06):
    print("hang rate",h)
    print("  timeout 135s, retry      ", loop(lambda h: call_plain(h,135), h))
    print("  timeout 30s, retry       ", loop(lambda h: call_plain(h,30), h))
    print("  timeout 20s, retry       ", loop(lambda h: call_plain(h,20), h))
    print("  timeout 12s, retry       ", loop(lambda h: call_plain(h,12), h))
    print("  hedge@9s, round cap 25s  ", loop(lambda h: call_hedged(h,9,25), h))
    print("  hedge@7s, round cap 20s  ", loop(lambda h: call_hedged(h,7,20), h))
    print("  hedge@5s, round cap 20s  ", loop(lambda h: call_hedged(h,5,20), h))
